#include "vm.h"
#include <string.h>

static void push(VM *vm, Value v) {
    if (vm->sp >= MAX_STACK) { fprintf(stderr, "stack overflow\n"); exit(1); }
    vm->stack[vm->sp++] = v;
}

static Value pop(VM *vm) {
    if (vm->sp <= 0) { fprintf(stderr, "stack underflow\n"); exit(1); }
    return vm->stack[--vm->sp];
}

static Value make_int(int64_t v) { Value val; val.type = VAL_INT; val.data.ival = v; return val; }
static Value make_str(const char *s) { Value val; val.type = VAL_STR; val.data.sval = strdup(s); return val; }
static Value make_bool(int b) { Value val; val.type = VAL_BOOL; val.data.bval = b; return val; }

static Value make_map(void) {
    Value val; val.type = VAL_MAP; val.data.map = malloc(sizeof(MapData));
    val.data.map->keys = NULL; val.data.map->values = NULL; val.data.map->len = 0; val.data.map->cap = 0;
    return val;
}

static int map_find(MapData *m, const char *key) {
    for (int i = 0; i < m->len; i++) if (strcmp(m->keys[i], key) == 0) return i;
    return -1;
}

static void map_set(MapData *m, const char *key, Value v) {
    int i = map_find(m, key);
    if (i >= 0) { m->values[i] = v; return; }
    if (m->len >= m->cap) {
        int cap = m->cap == 0 ? 8 : m->cap * 2;
        m->keys = realloc(m->keys, cap * sizeof(char*));
        m->values = realloc(m->values, cap * sizeof(Value));
        m->cap = cap;
    }
    m->keys[m->len] = strdup(key);
    m->values[m->len] = v;
    m->len++;
}

static int map_delete(MapData *m, const char *key) {
    int i = map_find(m, key);
    if (i < 0) return 0;
    free(m->keys[i]);
    for (int j = i; j < m->len - 1; j++) { m->keys[j] = m->keys[j+1]; m->values[j] = m->values[j+1]; }
    m->len--;
    return 1;
}


